fn nested(kind: char, levels: usize) -> String {
    match kind {
        'a' => format!("{}{}", "[".repeat(levels), "]".repeat(levels)),
        'o' => format!("{}1{}", "{\"a\":".repeat(levels), "}".repeat(levels)),
        _ => {
            let pairs = levels / 2;
            let (open, close) = if levels % 2 == 1 {
                ("[", "]")
            } else {
                ("", "")
            };
            format!(
                "{}0{}{open}{close}",
                "[{\"a\":".repeat(pairs),
                "}]".repeat(pairs)
            )
        }
    }
}

#[test]
fn test_fromjson_reads_to_jqs_parse_depth_ceiling_5688() -> Result<()> {
    for (kind, levels, stdout, stderr, status) in ROWS {
        let text = nested(*kind, *levels);
        let quoted = serde_json::to_string(&text)?;
        let (out, err, code) = run_jq_full(&["-c", "fromjson|[..]|length"], Some(&quoted))?;
        assert_eq!(
            (out.as_str(), err.as_str(), code),
            (*stdout, *stderr, *status),
            "{kind} x {levels}"
        );
    }
    Ok(())
}
